def proverb(*pieces, qualifier=None):
    if not pieces:
        return []

    lines = [
        "For want of a {} the {} was lost.".format(a, b)
        for a, b in zip(pieces, pieces[1:])
    ]

    first = pieces[0]
    if qualifier is not None:
        first = "{} {}".format(qualifier, first)
    lines.append("And all for the want of a {}.".format(first))

    return lines
